  stop("init should be either 'BC' or 'BCr'")

}

x <- na.omit(x)



if (is.unsorted(x)) {

  x.order <- order(x, decreasing = FALSE)

  x       <- x[x.order]

} else {

  x.order <- NULL

}

scalex <- 1

if (standardize) {

  scalex <- median(x)

  x <- x / scalex # so median is 1

