BC <- function(y, lambda, chg = NULL, stdToo = TRUE) {

  # The Box-Cox transformation.

  #

  if (lambda == 0) {

    yt <- log(y)

  } else {

    yt <- (y^lambda - 1) / lambda

  }

  if (stdToo) {

    if (length(y) > 1) {

      locScale <- estLocScale(matrix(yt, ncol = 1), 

                              type = "hubhub")

      zt <- (yt - locScale$loc) / locScale$scale

    } else { 

      zt <- yt

    }

  } else {

    zt <- NULL

  }

  return(list(yt = yt, zt =zt))

}

