        }else if (case=="U_id"){
            delta <- param[[1]]
            U_mean <- param[[2]]
            inter_shapley <- 2*tcrossprod(c_0)*cov_inv + 2*delta*tcrossprod(r_0)*cov_inv + 
                    + U_mean*tcrossprod(c_0,r_0)*cov_inv + U_mean*tcrossprod(r_0,c_0)*cov_inv
        }else if (case=="General"){
            e_UU <- param[[1]]
            psi <- param[[2]]
            inter_shapley <- 2*tcrossprod(c_0)*cov_inv + 1/2*tcrossprod(r_0)*e_UU*cov_inv +
                    + tcrossprod(c_0,r_0)*(cov_inv%*%psi) + tcrossprod(r_0,c_0)*(psi%*%cov_inv)
        }
        inter_shapley <- inter_shapley - diag(rowSums(inter_shapley/2))
        rownames(inter_shapley) <- colnames(inter_shapley) <- colnames(data)
        shapley_interaction[[rownames(data)[i]]] <- inter_shapley
    }
    return(shapley_interaction)
}

c_step <- function(z,m,data){

    d2 <- IMah_dist(data=data,z=z)
    updated_z <- rep(0,length(z))
    updated_z[order(d2)[1:m]] <- 1

    S <- int_cov_z(updated_z,data)
    mean_c <- int_mean_z(updated_z,as.matrix(data@Centers))
    mean_r <- int_mean_z(updated_z,as.matrix(data@Ranges))

    return(list(updated_z=updated_z, S=S, mean_c=mean_c, 
                mean_r=mean_r, robust_dist=d2))
}

#' Randomly draw a subset of observations
#' @keywords internal
#' @param m An integer specifying the number of observations to use
#' @param data An \code{\linkS4class{intData}} object containing the macrodata/interval data
#' @return A vector representing an m-length subset of X
draw_z 
step_it <- function(z, m, data, it = 0){
    res <- c_step(z, m, data)
    det_new <- det(res$S)
    z <- res$updated_z

    if(it==0){
        det_old <- Inf
        while(det_old > det_new && det_new > 0){
            res <- c_step(z, m, data)
            det_old <- det_new
            det_new <- det(res$S)
            z <- res$updated_z
        }
    } else{
        for (i in seq_len(it-1)){
            res <- c_step(z, m, data)
            z <- res$updated_z
        }
    }
    return(res)
}

